import { Test, TestingModule } from '@nestjs/testing';
import { PrismaService } from '../prisma/prisma.service';
import { RealtimeService } from '../realtime/realtime.service';
import { AlertsService } from './alerts.service';

describe('AlertsService', () => {
  let service: AlertsService;
  let prisma: PrismaService;
  let realtime: RealtimeService;

  const mockPrismaService = {
    alert: {
      create: jest.fn().mockResolvedValue({ 
        id: 1, 
        message: 'Front Door Opened', 
        severity: 'WARNING', 
        acknowledged: false, 
        timestamp: new Date() 
      }),
    },
  };

  const mockRealtimeService = {
    emit: jest.fn(),
  };

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        AlertsService,
        { provide: PrismaService, useValue: mockPrismaService },
        { provide: RealtimeService, useValue: mockRealtimeService },
      ],
    }).compile();

    service = module.get<AlertsService>(AlertsService);
    prisma = module.get<PrismaService>(PrismaService);
    realtime = module.get<RealtimeService>(RealtimeService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  it('should correctly save an alert and broadcast it', async () => {
    const testMessage = 'Front Door Opened';
    
    await service.createSystemAlert(testMessage);

    expect(prisma.alert.create).toHaveBeenCalledWith({
      data: { 
        message: testMessage,
        severity: 'WARNING',
        acknowledged: false  
      },
    });

    expect(realtime.emit).toHaveBeenCalledWith(
      'NEW_ALERT', 
      expect.objectContaining({ message: testMessage })
    );
  });
});